    "name": "roles/bigquery.dataEditor",
    "title": "BigQuery Data Editor",
    "description": "When granted on a dataset, this role grants these permissions: Get metadata and permissions for the dataset. For tables and views: Create, update, get, list, and delete the dataset's tables and views. Read (query), export, replicate, and update table data. Create, update, and delete indexes. Create and restore snapshots. All permissions for the dataset's routines and models. Note: Principals that are granted the Data Editor role at the project level can also create new datasets and list datasets in the project that they have access to. When granted on a table or view, this role grants these permissions: Get metadata, update metadata, get access controls, and delete the table or view. Get (query), export, replicate, and update table data. Create, update, and delete indexes. Create and restore snapshots. All permissions for the routine. The Data Editor role cannot be granted to individual models. Note: The BigQuery Data Editor role is mapped to the WRITER BigQuery basic role. When you grant the BigQuery Data Editor role to a principal at the dataset level, the principal is granted WRITER access to the dataset. Lowest-level resources where you can grant this role: Dataset These resources within a dataset: Table View Routine This role can also be granted on Resource Manager resources (projects, folders, and organizations).",
